import net.phoenix.chromatic_codes.api.IChromaticEffect;

IChromaticEffect custom = new IChromaticEffect() {
    @Override public int getRenderColor(int original,
        float x,
        float y) {
        return 0xFF0000;
    }
    @Override public float getXOffset(float x, float y) {
        return 0;
    }
    @Override public float getYOffset(float x, float y) {
        return 0;
    }
};

